<?php
namespace qqworld_collector\module\collect_filter; class dynamic_paging extends filter { public function filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { extract($args); $this->links = array(); $structure = apply_filters( 'qqworld-collector-collection-project-variable-filter', $structure, 0 ); if ($structure && !empty($keyword)) { $pages = array($from, $to); sort($pages); $new_link = $item; for ($i=0; $i<$pages[1]; $i++) { $keywords = $GLOBALS['QC']->collector->engine->advanced_request->get_keywrods($new_link, $keyword, array('download_args' => $download_args)); if (!empty($keywords)) { $new_link = $GLOBALS['QC']->collector->engine->advanced_request->get_new_link($keywords, $structure, $new_link); if (!$new_link) break; if ($i+1 >= $pages[0]) $this->links[] = $new_link; } } } $item = $this->links; return $item; } public function parse($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode) { if ($item) { if (is_string($item)) { if ( !preg_match('/\(disallowed:[^\)]*\)/i', $item) ) $item = $this->filter($item, $args, $source_link, $html, $type, $item_args, $download_args, $mode); } elseif (!empty($item)) { $temp = array(); foreach ($item as $i) { if ($i && !preg_match('/\(disallowed:[^\)]*\)/i', $i)) { $i = $this->filter($i, $args, $source_link, $html, $type, $item_args, $download_args, $mode); $temp = array_merge($temp, $i); } } $item = $temp; } } return $item; } } ?>